schema: voc-agent-card/1
id: mapper
version: 2
purpose: Maps one shard of one package for the repository's knowledge pack, one cited claim per note.
harness: converse
model: {id: global.anthropic.claude-haiku-5-5}
inputs:
  - {name: shard, from: task, required: true}
  - {name: checkout, from: checkout, required: true}
outputs:
  - {name: notes, schema: voc-note/1, recorded_on: task}
tools: [read_file, list_files, write_notes, report_progress, save_checkpoint, finish]
broker_ops: [read]
caps: {max_turns: 150, max_input_tokens: 120000}
trust: {untrusted: [repository], fence: nonce}
evals: []

schema: voc-agent-card/1
id: understander
version: 4
purpose: Reads an issue, classifies it (bug, feature or investigation) with a severity, finds the code involved and writes the problem statement and acceptance criteria; in the Tenets flow, drafts the repository's tenets.
harness: converse
model: {id: global.anthropic.claude-haiku-5-5}
inputs:
  - {name: issue, from: broker.read:issue, required: true, trust: data}
  - {name: knowledge, from: knowledge}
  - {name: memory, from: memory}
  - {name: tenets, from: broker.read:tenets, trust: data}
  - {name: checkout, from: checkout, required: true}
outputs:
  - {name: triage, schema: voc-triage/1, recorded_on: task}
  - {name: comment, kind: issue_comment, recorded_on: issue}
  - {name: labels, kind: issue_labels, recorded_on: issue}
  - {name: tenets, schema: voc-tenets/1, recorded_on: task}
  - {name: finish, kind: summary, recorded_on: task}
tools: [read_file, list_files, read_issue, write_triage, post_comment, label_issue, read_tenets, write_tenets,
        report_progress, save_checkpoint, finish]
broker_ops: [read, post_comment, label_issue]
caps: {max_turns: 150, max_input_tokens: 120000}
trust: {untrusted: [issue, repository, knowledge, memory, tenets], fence: nonce}
evals: [issue-triage/divide-floors, issue-triage/power-operation-request, issue-triage/slow-add-investigation,
        issue-triage/planted-instruction]

schema: voc-agent-card/1
id: hunter
version: 3
purpose: Confirms bugs from the issue, the tests and static signals, writes each with its evidence, and posts one fix task per confirmed bug.
harness: converse
model: {id: global.anthropic.claude-sonnet-5-5}
inputs:
  - {name: task, from: task, required: true}
  - {name: issue, from: broker.read:issue, trust: data}
  - {name: triage, from: understander.write_triage}
  - {name: checkout, from: checkout, required: true}
outputs:
  - {name: findings, schema: voc-finding/1, recorded_on: task}
  - {name: fix_tasks, kind: board_task, recorded_on: task}
tools: [read_file, list_files, run, install_dependencies, write_findings, post_subtask, read_issue, report_progress,
        save_checkpoint, finish]
broker_ops: [read]
caps: {max_turns: 150, max_input_tokens: 120000}
trust: {untrusted: [issue, repository, command_output, knowledge, memory], fence: nonce}
evals: [bug-hunt-and-fix/divide-floor-bug, bug-hunt-and-fix/slug-cut-bug, bug-hunt-and-fix/monorepo-units-bug]

schema: voc-agent-card/1
id: fixer
version: 3
purpose: Smallest fix for one confirmed bug, with a test that fails without it.
harness: converse
model: {id: global.anthropic.claude-sonnet-5-5}
inputs:
  - {name: bug, from: hunter.post_subtask, required: true}
  - {name: problem_statement, from: understander.write_triage}
  - {name: issue, from: broker.read:issue, trust: data}
  - {name: checkout, from: checkout, required: true}
outputs:
  - {name: patch, kind: submitted_patch, recorded_on: task}
  - {name: finish, kind: summary, recorded_on: task}
tools: [read_file, list_files, write_file, run, install_dependencies, submit_work, read_issue, report_progress,
        save_checkpoint, finish]
broker_ops: [read]
caps: {max_turns: 150, max_input_tokens: 120000}
trust: {untrusted: [issue, repository, command_output, knowledge, memory], fence: nonce}
evals: [bug-hunt-and-fix/divide-floor-bug, bug-hunt-and-fix/slug-cut-bug, bug-hunt-and-fix/monorepo-units-bug]

schema: voc-agent-card/1
id: builder
version: 2
purpose: Builds a feature from an issue or a PRD with a test for every acceptance criterion, posting its parts as sub-builds.
harness: converse
model: {id: global.anthropic.claude-sonnet-5-5}
inputs:
  - {name: feature, from: task, required: true}
  - {name: problem_statement, from: understander.write_triage}
  - {name: checkout, from: checkout, required: true}
outputs:
  - {name: patch, kind: submitted_patch, recorded_on: task}
  - {name: sub_builds, kind: board_task, recorded_on: task}
tools: [read_file, list_files, write_file, run, install_dependencies, submit_work, post_subtask, report_progress,
        save_checkpoint, finish]
broker_ops: [read]
caps: {max_turns: 150, max_input_tokens: 120000}
trust: {untrusted: [repository, command_output, knowledge, memory], fence: nonce}
evals: [feature/duration-hours-feature]

schema: voc-agent-card/1
id: committer
version: 3
purpose: After the quality gate's GO, has the broker push the submitted patch as one commit to the run's branch.
harness: converse
model: {id: global.anthropic.claude-sonnet-5-5}
inputs:
  - {name: patch, from: fixer.submit_work, required: true}
  - {name: go, from: final-go.write_gate_record, required: true}
  - {name: how_we_work, from: knowledge}
  - {name: issue, from: broker.read:issue, trust: data}
outputs:
  - {name: commit, kind: pushed_branch, recorded_on: branch}
tools: [read_file, list_files, push_commit, read_issue, report_progress, save_checkpoint, finish]
broker_ops: [read, push_bundle]
caps: {max_turns: 150, max_input_tokens: 120000}
trust: {untrusted: [issue, repository, knowledge], fence: nonce}
evals: [bug-hunt-and-fix/divide-floor-bug, bug-hunt-and-fix/slug-cut-bug]

schema: voc-agent-card/1
id: commit-reviewer
version: 2
purpose: Reviews one submitted change against the repository's review guide before the quality gate; scope creep is blocking.
harness: converse
model: {id: global.anthropic.claude-sonnet-5-5}
inputs:
  - {name: change, from: fixer.submit_work, required: true}
  - {name: task, from: task, required: true}
  - {name: review_guide, from: knowledge}
  - {name: checkout, from: checkout, required: true}
outputs:
  - {name: findings, schema: voc-finding/1, recorded_on: task}
  - {name: verdict, kind: summary, recorded_on: task}
tools: [read_file, list_files, write_findings, report_progress, save_checkpoint, finish]
broker_ops: [read]
caps: {max_turns: 150, max_input_tokens: 120000}
trust: {untrusted: [repository, knowledge, board], fence: nonce}
evals: [bug-hunt-and-fix/divide-floor-bug, bug-hunt-and-fix/slug-cut-bug]

schema: voc-agent-card/1
id: gate-runner
version: 3
purpose: Runs the quality gate's language packs on the submitted change's tree and records what they say.
harness: converse
model: {id: global.anthropic.claude-haiku-5-5}
inputs:
  - {name: patch, from: fixer.submit_work, required: true}
  - {name: gate_plan, from: flow, required: true}
  - {name: checkout, from: checkout, required: true}
outputs:
  - {name: gate_record, schema: voc-gate-record/1, recorded_on: task}
tools: [read_file, list_files, run, install_dependencies, write_gate_record, run_gate, report_progress, save_checkpoint,
        finish]
broker_ops: [read]
caps: {max_turns: 150, max_input_tokens: 120000}
trust: {untrusted: [repository, command_output], fence: nonce}
evals: [bug-hunt-and-fix/divide-floor-bug, bug-hunt-and-fix/monorepo-units-bug]

schema: voc-agent-card/1
id: pr-author
version: 3
purpose: Writes the pull request's title and description from the run's reports and has the broker open it from the run's branch.
harness: converse
model: {id: global.anthropic.claude-sonnet-5-5}
inputs:
  - {name: reports, from: task, required: true}
  - {name: gate_record, from: final-go.write_gate_record, required: true}
  - {name: issue, from: broker.read:issue, trust: data}
outputs:
  - {name: pull_request, kind: pull_request, recorded_on: pull_request}
tools: [read_file, list_files, open_draft_pr, read_issue, report_progress, save_checkpoint, finish]
broker_ops: [read, open_or_update_draft_pr]
caps: {max_turns: 150, max_input_tokens: 120000}
trust: {untrusted: [issue, repository, board], fence: nonce}
evals: [bug-hunt-and-fix/divide-floor-bug, bug-hunt-and-fix/slug-cut-bug]

schema: voc-agent-card/1
id: pr-reviewer
version: 2
purpose: Reviews a pull request with the repository's tenets and review guide and comments on it; never an approval.
harness: converse
model: {id: global.anthropic.claude-sonnet-5-5}
inputs:
  - {name: pages, from: task, required: true}
  - {name: review_guide, from: knowledge}
  - {name: pull_request, from: broker.read:pull_request, trust: data}
outputs:
  - {name: findings, schema: voc-finding/1, recorded_on: task}
  - {name: comment, kind: pull_request_comment, recorded_on: pull_request}
tools: [read_file, list_files, write_findings, post_comment, report_progress, save_checkpoint, finish]
broker_ops: [read, post_comment]
caps: {max_turns: 150, max_input_tokens: 120000}
trust: {untrusted: [pull_request, repository, knowledge], fence: nonce}
evals: [pr-review/pagination-review]

schema: voc-agent-card/1
id: final-go
version: 3
purpose: The quality gate's last word, by an agent that neither wrote nor reviewed the change - GO or NO-GO with its reasons.
harness: converse
model: {id: global.anthropic.claude-opus-5-5}
inputs:
  - {name: patch, from: fixer.submit_work, required: true}
  - {name: gate_record, from: gate-runner.write_gate_record, required: true}
  - {name: findings, from: commit-reviewer.write_findings}
  - {name: checkout, from: checkout, required: true}
outputs:
  - {name: verdict, schema: voc-gate-record/1, recorded_on: task}
tools: [read_file, list_files, write_gate_record, read_gate_record, read_findings, report_progress, save_checkpoint,
        finish]
broker_ops: [read]
caps: {max_turns: 150, max_input_tokens: 120000}
trust: {untrusted: [repository, board, command_output], fence: nonce}
evals: [bug-hunt-and-fix/divide-floor-bug, bug-hunt-and-fix/slug-cut-bug]

schema: voc-agent-card/1
id: coordinator
version: 5
purpose: Follows the run's flow, posts each step's tasks for the roles it takes and launches their agents; changes no code.
harness: converse
model: {id: global.anthropic.claude-sonnet-5-5}
inputs:
  - {name: goal, from: task, required: true}
  - {name: flow, from: flow}
  - {name: board, from: board}
  - {name: knowledge, from: knowledge}
  - {name: issue, from: broker.read:issue, trust: data}
outputs:
  - {name: tasks, kind: board_task, recorded_on: task}
  - {name: finish, kind: summary, recorded_on: task}
tools: [read_flow, read_board, post_task, launch_agent, complete_step, fan_out, read_knowledge, read_file, list_files,
        read_issue, relay_steering, set_direction, report_progress, save_checkpoint, finish]
broker_ops: [read]
caps: {max_turns: 150, max_input_tokens: 120000}
trust: {untrusted: [issue, repository, knowledge, board, memory], fence: nonce}
evals: [bug-hunt-and-fix/divide-floor-bug, bug-hunt-and-fix/slug-cut-bug, feature/duration-hours-feature]

# Learn's card: the coach is never launched as an agent. Learn is a built-in, final step of every flow (the flow's
# `learn` settings): the run's retrospective, the roles' lessons (an administrator approves each) and the coach's
# skill proposals, each naming the eval case it should gain on (the benchmark gate, then an administrator's accept).
schema: voc-agent-card/1
id: coach
version: 1
purpose: Learns from a finished run - its retrospective, the roles' lessons and the coach's skill proposals, each naming its eval case.
harness: learn
model: {id: global.anthropic.claude-opus-5-5}
inputs:
  - {name: transcripts, from: transcripts, required: true, trust: data}
  - {name: board, from: board, required: true}
  - {name: skills, from: flow}
outputs:
  - {name: retrospective, kind: scorecard, recorded_on: skills}
  - {name: lessons, kind: lesson_draft, recorded_on: skills}
  - {name: proposals, kind: skill_proposal, recorded_on: skills}
tools: []
broker_ops: []
caps: {}
trust: {untrusted: [transcripts, board, repository, command_output], fence: nonce}
evals: [bug-hunt-and-fix/divide-floor-bug, bug-hunt-and-fix/slug-cut-bug, feature/duration-hours-feature,
        pr-review/pagination-review]

schema: voc-flow-template/1
id: bug-hunt-and-fix
version: 3
name: Bug hunt and fix
description: Hunts bugs in the packages it is given, fixes and reviews each one, runs the quality gate and stops at a pull request ready for review.
inputs:
  issue: {type: issue_ref}
  triage: {type: voc-triage/1}
  feedback: {type: feedback_ids, max: 50}
budget: {monthly_usd: 50, run_token_cap: 3000000, max_tasks: 40}
memory: {recall: true, scopes: [repo, role], limit: 10}
learn:
  enabled: true
  model: global.anthropic.claude-sonnet-5-5
  budget_share: 0.05
  roles: [hunter, fixer, commit-reviewer, gate-runner, final-go]
  after_needs_human_hours: 72
  assert: [{check: learn.proposals_name_case}]
pr: ready
requires: {dial: [ai_assisted, ai_driven], ci_attestation: true, image: true, issues_source: false}
steps:
  - id: hunt
    title: Hunt bugs
    agent: hunter@latest
    assert:
      - {check: findings.cite_evidence, on_fail: block}
      - {check: tasks.posted, args: {role: fixer, min: 1}, on_fail: block}
  - id: board
    title: Fix and review each bug
    board: {posters: [hunter], claimers: [fixer, commit-reviewer], until: drained}
    assert:
      - {check: patch.submitted, on_fail: block}
      - {check: patch.touches_tests, on_fail: block}
      - {check: patch.no_ci_changes, on_fail: block}
      - {check: review.no_blocking, args: {by: commit-reviewer}, on_fail: block}
  - id: gate
    title: Quality gate
    quality_gate: {packs: auto, max_rounds: 3, runner: gate-runner@latest, final_go: final-go@latest}
    assert:
      - {check: gate.pack_checks_ran, on_fail: block}
      - {check: gate.passed, on_fail: fail_arrow}
    on: {pass: commit, fail: human}
  - id: commit
    title: Commit the fix the gate passed
    agent: committer@latest
    instructions: Commit the fixer's submitted patch, the tree the gate's GO names, to the run's branch.
    assert: [{check: push.tree_is_judged_tree, on_fail: block}]
  - id: pr_author
    title: Open the pull request
    agent: pr-author@latest
    instructions: "Open the pull request for the fix: the bug it fixes (how it showed and where), what was changed to fix it, the test that proves it, the gate record and the feedback ids it cites; say Fixes #N for the run's issue. Never merge."
    assert:
      - {check: pr.opened, on_fail: block}
      - {check: pr.state_as_flow, on_fail: block}
      - {check: pr.links_issue, on_fail: warn}
  - {id: pr, title: Pull request, stop_at_pr: {}}
  - {id: human, title: A person decides, end: {status: needs_human}}

schema: voc-flow-template/1
id: feature
version: 2
name: Feature from an issue or a PRD
description: "Builds a feature from an issue or a PRD: understands it, plans, builds, commits and reviews, runs the quality gate and stops at a pull request ready for review."
inputs:
  issue: {type: issue_ref}
  prd: {type: prd_ref}
  feedback: {type: feedback_ids, max: 50}
budget: {monthly_usd: 50, run_token_cap: 3000000, max_tasks: 40}
memory: {recall: true, scopes: [repo, role], limit: 10}
learn:
  enabled: true
  model: global.anthropic.claude-sonnet-5-5
  budget_share: 0.05
  roles: [understander, builder, commit-reviewer, gate-runner, final-go]
  after_needs_human_hours: 72
  assert: [{check: learn.proposals_name_case}]
pr: ready
requires: {dial: [ai_assisted, ai_driven], ci_attestation: true, image: true, issues_source: false}
steps:
  - {id: understand, title: Understand the issue or PRD, agent: understander@latest}
  - {id: plan, title: Plan the work, agent: coordinator@latest}
  - id: board
    title: Build and review each task
    board: {posters: [coordinator], claimers: [builder, commit-reviewer], until: drained}
    assert:
      - {check: patch.submitted, on_fail: block}
      - {check: patch.touches_tests, on_fail: block}
      - {check: patch.no_ci_changes, on_fail: block}
      - {check: review.no_blocking, args: {by: commit-reviewer}, on_fail: block}
  - id: gate
    title: Quality gate
    quality_gate: {packs: auto, max_rounds: 3, runner: gate-runner@latest, final_go: final-go@latest}
    assert:
      - {check: gate.pack_checks_ran, on_fail: block}
      - {check: gate.passed, on_fail: fail_arrow}
    on: {pass: commit, fail: human}
  - id: commit
    title: Commit the build the gate passed
    agent: committer@latest
    instructions: Commit the builders' submitted patch, the tree the gate's GO names, to the run's branch.
    assert: [{check: push.tree_is_judged_tree, on_fail: block}]
  - id: pr_author
    title: Open the pull request
    agent: pr-author@latest
    instructions: Open the pull request with what was built, what it was built from (the issue or the PRD), the methodology steps it went without, the gate record and the feedback ids it cites. Never merge.
    assert:
      - {check: pr.opened, on_fail: block}
      - {check: pr.state_as_flow, on_fail: block}
  - {id: pr, title: Pull request, stop_at_pr: {}}
  - {id: human, title: A person decides, end: {status: needs_human}}
